const content = String($json.content ?? '');

if (!content.trim()) {
  throw new Error('Google Docs returned an empty CV.');
}

// Deterministic hash of the CV text.
// Identical CV text = identical version.
// Changed CV text = different version.
let hash1 = 2166136261;
let hash2 = 2166136261 ^ 0x9e3779b9;

for (let i = 0; i < content.length; i++) {
  const code = content.charCodeAt(i);

  hash1 ^= code;
  hash1 = Math.imul(hash1, 16777619);

  hash2 ^= (code + i);
  hash2 = Math.imul(hash2, 2246822519);
}

const part1 = (hash1 >>> 0).toString(16).padStart(8, '0');
const part2 = (hash2 >>> 0).toString(16).padStart(8, '0');

return {
  json: {
    ...$json,
    candidate_id: 'Susmita Kayal',
    cv_version: `${part1}-${part2}`
  }
};

