parameters.jsCode:
const content = $json.choices?.[0]?.message?.content;

if (!content) {
  throw new Error('Groq Role Fit returned no message content.');
}

let parsed;

try {
  parsed = JSON.parse(content);
} catch (error) {
  throw new Error(
    'Could not parse Groq Role Fit JSON: ' + error.message
  );
}

const requiredFields = [
  'overall_fit_score',
  'fit_level',
  'recommendation',
  'overall_hiring_assessment',
  'skills_tools_mapping',
  'language_mapping',
  'domain_mapping',
  'functional_responsibility_mapping',
  'transferable_experience',
  'gaps_risks_evidence_gaps',
  'hiring_manager_view',
  'executive_summary'
];

for (const field of requiredFields) {
  if (!(field in parsed)) {
    throw new Error(
      `Groq Role Fit response is missing required field: ${field}`
    );
  }
}

if (
  typeof parsed.overall_fit_score !== 'number' ||
  parsed.overall_fit_score < 0 ||
  parsed.overall_fit_score > 100
) {
  throw new Error('Invalid overall_fit_score returned by Groq.');
}

if (typeof parsed.fit_level !== 'string') {
  throw new Error('fit_level must be a string.');
}

if (typeof parsed.recommendation !== 'string') {
  throw new Error('recommendation must be a string.');
}

if (typeof parsed.overall_hiring_assessment !== 'string') {
  throw new Error(
    'overall_hiring_assessment must be a string.'
  );
}

const arrayFields = [
  'skills_tools_mapping',
  'language_mapping',
  'domain_mapping',
  'functional_responsibility_mapping',
  'transferable_experience',
  'gaps_risks_evidence_gaps'
];

for (const field of arrayFields) {
  if (!Array.isArray(parsed[field])) {
    throw new Error(`${field} must be an array.`);
  }
}

if (
  typeof parsed.hiring_manager_view !== 'object' ||
  parsed.hiring_manager_view === null ||
  Array.isArray(parsed.hiring_manager_view)
) {
  throw new Error('hiring_manager_view must be an object.');
}

const hiringManagerFields = [
  'shortlist_decision',
  'why',
  'interview_validation_points',
  'progression_blockers'
];

for (const field of hiringManagerFields) {
  if (!(field in parsed.hiring_manager_view)) {
    throw new Error(
      `hiring_manager_view is missing required field: ${field}`
    );
  }
}

if (
  !Array.isArray(
    parsed.hiring_manager_view.interview_validation_points
  )
) {
  throw new Error(
    'hiring_manager_view.interview_validation_points must be an array.'
  );
}

if (
  !Array.isArray(
    parsed.hiring_manager_view.progression_blockers
  )
) {
  throw new Error(
    'hiring_manager_view.progression_blockers must be an array.'
  );
}

if (typeof parsed.executive_summary !== 'string') {
  throw new Error('executive_summary must be a string.');
}

return {
  json: {
    ...$json,
    output: parsed
  }
};

const rows = $input.all();

const selected = [];

for (const item of rows) {
  const row = item.json;

  const ingestionStatus = String(
    row.ingestion_status ?? ""
  ).trim().toUpperCase();

  const agent3Status = String(
    row.agent3_status ?? ""
  ).trim().toUpperCase();

  // Only jobs that are newly ingested and have not
  // already been successfully processed by Agent 3.
  if (
    ingestionStatus === "NEW" &&
    agent3Status !== "SUCCESS"
  ) {
    selected.push(item);

    if (selected.length >= 20) {
      break;
    }
  }
}

// Nothing left to process.
// Returning zero items gives the continuation logic
// a clean termination condition.
if (selected.length === 0) {
  return [];
}

return selected;

const items = $input.all();

if (!items.length) {
  throw new Error(
    "Prepare Agent 3 Context: Merge returned no items."
  );
}

// First, look for the candidate profile in the current Merge input.
let candidateItem = items.find((item) => {
  const data = item.json ?? {};

  return (
    String(data.candidate_profile ?? "").trim() !== "" &&
    String(data.job_key ?? "").trim() === ""
  );
});

// On subsequent continuous batches, Merge may contain only jobs.
// Fall back to the already-executed candidate lookup node.
let candidate;

if (candidateItem) {
  candidate = candidateItem.json;
} else {
  try {
    candidate = $("Get row(s)").first().json;
  } catch (error) {
    throw new Error(
      "Prepare Agent 3 Context: Candidate profile was not found in Merge or Get row(s)."
    );
  }
}

const candidateId = String(
  candidate.candidate_id ?? "unknown"
).trim();

const candidateProfile = String(
  candidate.candidate_profile ?? ""
).trim();

if (!candidateProfile) {
  throw new Error(
    "Prepare Agent 3 Context: Candidate profile is empty."
  );
}

// Identify the job records in the current Merge input.
const jobs = items.filter((item) => {
  const data = item.json ?? {};

  return String(data.job_key ?? "").trim() !== "";
});

if (!jobs.length) {
  throw new Error(
    "Prepare Agent 3 Context: No job records found in Merge output."
  );
}

// Build one Agent 3 context per job.
return jobs.map((item, index) => {
  const job = item.json;

  const jobKey = String(
    job.job_key ?? ""
  ).trim();

  if (!jobKey) {
    throw new Error(
      `Prepare Agent 3 Context: Job ${index + 1} has no job_key.`
    );
  }

  return {
    json: {
      job_key: jobKey,

      role: String(job.role ?? ""),
      company: String(job.company ?? ""),
      location: String(job.location ?? ""),
      country: String(job.country ?? ""),

      job_intelligence: {
        ...job,
      },

      candidate_id: candidateId,

      candidate_evidence: {
        candidate_id: candidateId,
        candidate_profile: candidateProfile,
        cv_version: String(
          candidate.cv_version ?? ""
        ),
      },

      evidence_boundary:
        "Use only the supplied job data and candidate evidence. Do not invent candidate skills, tools, experience, responsibilities, domains, certifications, languages, or qualifications. Distinguish direct evidence, transferable evidence, missing evidence, and evidence gaps."
    }
  };
});
